-- Нарезка построения меню по кадрам: пока меню строится (NB.Building), create() отдаёт кадр движку
-- каждые ~7 мс работы. Работает только в главном потоке скрипта, обработчики событий никогда не засыпают.
NB.Building = true
local NB_Main = coroutine.running()
local NB_SliceAt = os.clock()
local function NB_Slice()
	if NB.Building and os.clock() - NB_SliceAt > 0.007 and coroutine.running() == NB_Main then
		NB_RealRS.Heartbeat:Wait()
		NB_SliceAt = os.clock()
	end
end

local function NB_Track(conn)
	local list = NB.Conns
	list[#list + 1] = conn
	if #list % 256 == 0 then -- чистим уже отключённые
		local n, j = #list, 0
		for i = 1, n do
			local c = list[i]
			if c.Connected then
				j += 1
				list[j] = c
			end
		end
		for i = n, j + 1, -1 do list[i] = nil end
	end
	return conn
end

local function NB_Signal(sig)
	return {
		Connect = function(_, f) return NB_Track(sig:Connect(f)) end,
		Once = function(_, f) return NB_Track(sig:Once(f)) end,
		Wait = function() return sig:Wait() end,
	}
end

local function NB_Proxy(real, signals, special)
	local cache = {}
	return setmetatable({}, {
		__index = function(_, k)
			if signals[k] then
				local s = cache[k]
				if not s then
					s = NB_Signal(real[k])
					cache[k] = s
				end
				return s
			end
			if special and special[k] then return special[k] end
			local v = real[k]
			if type(v) == _0OlllII0[86] then
				return function(_, ...) return v(real, ...) end
			end
			return v
		end,
		__newindex = function(_, k, v) real[k] = v end,
	})
end

local RunService = NB_Proxy(NB_RealRS, { RenderStepped = true, Heartbeat = true, Stepped = true }, {
	BindToRenderStep = function(_, name, priority, fn)
		NB.Binds[#NB.Binds + 1] = name
		return NB_RealRS:BindToRenderStep(name, priority, fn)
	end,
})
local NB_UIS = NB_Proxy(NB_RealUIS, { InputBegan = true, InputChanged = true, InputEnded = true })

-- ================= ПРОИЗВОДИТЕЛЬНОСТЬ =================
-- NB.Frame растёт каждый кадр (для мемоизации на кадр), NB.Perf.Scale() растягивает
-- интервалы тяжёлых пересчётов, когда FPS проседает, и в "Лёгком режиме".
NB.Frame = 0
NB.Perf = { Fps = 60, Light = false }
do
	local ema = 60
	NB_RealRS:BindToRenderStep(_0OlllII0[106], Enum.RenderPriority.First.Value, function(dt)
		NB.Frame += 1
		if dt and dt > 0 then
			local inst = 1 / dt
			ema += (inst - ema) * 0.1
			NB.Perf.Fps = ema
		end
	end)
	NB.Binds[#NB.Binds + 1] = _0OlllII0[106]
	-- 1x при 60+ FPS; плавно до ~2.2x при 30 FPS; жёстче в лёгком режиме
	function NB.Perf.Scale()
		local f = NB.Perf.Fps
		local sc = f >= 58 and 1 or math.clamp(60 / math.max(f, 12), 1, 2.4)
		if NB.Perf.Light then sc = math.max(sc, 1.6) end
		return sc
	end
end

function NB.Cleanup()
	NB.Dead = true
	for _, f in ipairs(NB.CleanupFns) do pcall(f) end -- модули игр возвращают изменённые значения / камеру
	for _, c in ipairs(NB.Conns) do pcall(function() c:Disconnect() end) end
	table.clear(NB.Conns)
	for _, n in ipairs(NB.Binds) do pcall(function() NB_RealRS:UnbindFromRenderStep(n) end) end
	pcall(NB_Sweep)
	pcall(function()
		NB_RealUIS.MouseIconEnabled = true
		NB_RealUIS.MouseBehavior = Enum.MouseBehavior.Default
	end)
end
NB_ENV.NeverBloxCleanup = NB.Cleanup

-- Консоль разработчика: кольцевой буфер + перехват вывода игры
NB.LogBuf = {}
NB.LogGame = true
NB.LogUI = true
NB.T0 = os.clock()
NB.Sinks = {} -- подписчики на новые записи (консоль загрузки слева от карточки)
function NB.Log(kind, msg)
	local buf = NB.LogBuf
	msg = tostring(msg)
	for i = #buf, math.max(1, #buf - 40), -1 do
		local e = buf[i]
		if e.k == kind and e.m == msg then
			e.c = (e.c or 1) + 1
			e.t = os.date(_0OlllII0[107])
			if NB.LogHook then NB.LogHook() end
			return
		end
	end
	local entry = { t = os.date(_0OlllII0[107]), k = kind, m = msg, ms = math.floor((os.clock() - NB.T0) * 1000) }
	buf[#buf + 1] = entry
	if #buf > 3000 then table.remove(buf, 1) end
	if NB.LogHook then NB.LogHook() end
	for _, f in ipairs(NB.Sinks) do pcall(f, entry) end
end
pcall(function()
	local LS = game:GetService(_0OlllII0[108])
	local c = LS.MessageOut:Connect(function(msg, mt)
		if not NB.LogGame then return end
		local k = _0OlllII0[109]
		if mt == Enum.MessageType.MessageError then k = _0OlllII0[110]
		elseif mt == Enum.MessageType.MessageWarning then k = _0OlllII0[111] end
		NB.Log(k, msg)
	end)
	NB.Conns[#NB.Conns + 1] = c
end)

-- Защита от репортов ошибок. Игры вешают свои обработчики на ScriptContext.Error и шлют на сервер
-- текст ошибки, если в нём есть "head", "esp", "aimbot", "getgenv" и т.п. (Flick: InputMangaer -> ReplicatedStorage.op).
-- Чужие обработчики отключаем через getconnections; проверяем раз в 3 сек - скрипты могут подключиться позже.
-- При выгрузке меню всё включается обратно.
do
	local G = { list = {}, count = 0, ok = type(getconnections) == _0OlllII0[86] }
	NB.ErrGuard = G
	local function sweep()
		if not G.ok then return end
		local okC, conns = pcall(getconnections, game:GetService(_0OlllII0[112]).Error)
		if not okC or type(conns) ~= _0OlllII0[30] then return end
		for _, c in ipairs(conns) do
			local okE, en = pcall(function() return c.Enabled end)
			if not (okE and en == false) and pcall(function() c:Disable() end) then
				G.list[#G.list + 1] = c
				G.count += 1
			end
		end
	end
	G.sweep = sweep
	pcall(sweep)
	task.spawn(function()
		while not NB.Dead do
			task.wait(3)
			pcall(sweep)
		end
	end)
	NB.CleanupFns = NB.CleanupFns or {}
	NB.CleanupFns[#NB.CleanupFns + 1] = function()
		for _, c in ipairs(G.list) do pcall(function() c:Enable() end) end
		table.clear(G.list)
	end
end

