-- ОГРАНИЧЕННЫЙ РЕЖИМ (выключен по умолчанию, включается вручную). В нём грузятся только Конфиги, Аим и ESP без чамсов.
-- Не загружаются: чамсы, мир, настройки персонажа ("Я"), экранные индикаторы, скинченджер, движение,
-- игровые модули и всё остальное. Включается только вручную: список ID ниже или getgenv().NEVERBLOX_RESTRICT = true.
-- Принудительно: getgenv().NEVERBLOX_RESTRICT = true (включить) / false (выключить) до запуска скрипта.
----------------------------------------------------------------
NB.RestrictIds = {} -- сюда можно вписать PlaceId / GameId вручную
NB.Restricted = false
do
	local forced = NB_ENV.NEVERBLOX_RESTRICT
	if forced ~= nil then
		NB.Restricted = forced == true
	else
		for _, id in ipairs(NB.RestrictIds) do
			if game.PlaceId == id or game.GameId == id then NB.Restricted = true end
		end
	end
end
local RESTRICT_ALLOW = {
	[_0OlllII0[114]] = true, [_0OlllII0[115]] = true, [_0OlllII0[116]] = true,
	[_0OlllII0[117]] = true, [_0OlllII0[118]] = true,
}

-- Безопасный запуск модуля: ошибка в одном модуле не валит всё меню
local function Safe(name, fn)
	if NB.Restricted and not RESTRICT_ALLOW[name] then
		NB.Log(_0OlllII0[71], _0OlllII0[119] .. name)
		return true
	end
	NB.LastModule = name
	NB.Log(_0OlllII0[120], _0OlllII0[121] .. name)
	local t0 = os.clock()
	local ok, err = xpcall(fn, function(e) return tostring(e) .. _0OlllII0[122] .. debug.traceback() end)
	if ok and os.clock() - t0 > 0.25 then
		NB.Log(_0OlllII0[120], string.format(_0OlllII0[123], name, (os.clock() - t0) * 1000))
	end
	if not ok then
		NB.Failed[#NB.Failed + 1] = name
		NB.Log(_0OlllII0[110], _0OlllII0[124] .. name .. _0OlllII0[125] .. tostring(err))
		NB.Log(_0OlllII0[110], _0OlllII0[124] .. name .. _0OlllII0[125] .. tostring(err))
	end
	return ok
end

----------------------------------------------------------------
-- SAFE MODE (по умолчанию включён): пока он включён, код чамсов вообще не загружается
----------------------------------------------------------------
local SAFE = { On = true, Locks = {}, Listeners = {} }
if NB.Restricted then SAFE.On = true end -- в ограниченном режиме чамсы выключены всегда
function SAFE.OnChange(f)
	SAFE.Listeners[#SAFE.Listeners + 1] = f
end
function SAFE.Set(v)
	v = v and true or false
	if NB.Restricted and not v then return end -- Safe Mode нельзя выключить в ограниченном режиме
	if SAFE.On == v then return end
	SAFE.On = v
	-- сначала интерфейс (замки), потом тяжёлая часть - ошибка в одном месте не мешает остальному
	for _, L in ipairs(SAFE.Locks) do
		local ok, err = pcall(L.Update, v)
		if not ok then NB.Log(_0OlllII0[110], _0OlllII0[126] .. tostring(err)) end
	end
	for _, f in ipairs(SAFE.Listeners) do
		local ok, err = pcall(f, v)
		if not ok then NB.Log(_0OlllII0[110], _0OlllII0[127] .. tostring(err)) end
	end
end

