function Library:Select(tab)
	if self.Current == tab or self.Animating then return end
	if tab.Lazy and not tab.Lazy.done then
		-- вкладка игры: сначала подгружаем её модуль (с анимацией), потом открываем
		if not NB.LoadGame(tab) then return end
		if self.Current == tab or self.Animating then return end
	end
	self.Animating = true
	local oldTab = self.Current

	for _, t in ipairs(self.Tabs) do
		local on = (t == tab) or (tab.HubParent == t)
		tween(t.Button, { BackgroundTransparency = on and 0 or 1 })
		tween(t.Text, { TextColor3 = on and Theme.Text or Theme.Dim })
		if t.IconImg then tween(t.IconImg, { ImageColor3 = on and Theme.Accent or Theme.Dim }) end
		if t.IconLbl then tween(t.IconLbl, { TextColor3 = on and Theme.Accent or Theme.Dim }) end
		if t.IconParts then
			for _, p in ipairs(t.IconParts) do tween(p, { BackgroundColor3 = on and Theme.Accent or Theme.Dim }) end
		end
	end
	self.Current = tab

	if oldTab then
		tween(oldTab.Page, { Position = UDim2.fromOffset(0, -8) }, 0.1)
		task.wait(0.09)
		oldTab.Page.Visible = false
	end

	tab.Page.Position = UDim2.fromOffset(0, 10)
	tab.PageScale.Scale = 0.975
	tab.Page.Visible = true
	tween(tab.PageScale, { Scale = 1 }, 0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
	local tw = tween(tab.Page, { Position = UDim2.fromOffset(0, 0) }, 0.24, Enum.EasingStyle.Quart)
	tw.Completed:Connect(function() self.Animating = false end)
end


