				for p in pairs(data.parts) do
					if p.Parent then p.LocalTransparencyModifier = 0 end
				end
				for d, t in pairs(data.decals) do
					if d.Parent then d.Transparency = t end
				end
				hidden[ch] = nil
			end
			return
		end
		for _, plr in ipairs(Players:GetPlayers()) do
			local ch = plr.Character
			local hum = ch and ch:FindFirstChildOfClass(_0OlllII0[214])
			if plr ~= LocalPlayer and hum and hum.Health <= 0 then
				local data = hidden[ch]
