			end
			if W.NoBodies or next(hidden) then pcall(bodiesStep) end
			if tick % 4 == 0 and (W.NoFx or W.SmokeOn) then
				for _, f in ipairs(snapshot(fxs)) do pcall(applyFx, f) end
			end
		end
	end)

