	-- держим ровно n видимых элементов пула
	local function wxSetCount(kind, n, folder, camPos)
		local pool = wxPool[kind]
		if pool.shown == n then return end
		for i = #pool.parts + 1, n do
			pool.parts[i] = wxMake(kind)
			pool.pos[i] = camPos + Vector3.new(
				(math.random() * 2 - 1) * WX_HALF, WX_BOT + math.random() * (WX_TOP - WX_BOT), (math.random() * 2 - 1) * WX_HALF)
			pool.ph[i] = math.random() * 6.28
		end
		for i = 1, #pool.parts do
			local p = pool.parts[i]
			if i <= n then
				if p.Parent ~= folder then p.Parent = folder end
			elseif p.Parent then
				p.Parent = nil
			end
		end
		pool.shown = n
	end

