		if not cam then return end
		dt = math.min(dt or 0.016, 0.1)
		local camPos = cam.CFrame.Position
		local folder = wxContainer(cam)
		wxActive = true

		-- под крышей осадки почти исчезают
		if os.clock() - lastCover > 0.25 then
			lastCover = os.clock()
			rayParams.FilterDescendantsInstances = { cam, LocalPlayer.Character }
