local function updateCircle()
	local cam = workspace.CurrentCamera
	if not cam then return end
	if not Aim.ShowCircle or NB.Restricted then
		if fovCircle.Visible then
			fovCircle.Visible = false
			fovGlow.Visible = false
		end
		return
	end
	local d = 2 * (math.tan(math.rad(math.clamp(Aim.Fov, 1, 179) / 2)) / math.tan(math.rad(cam.FieldOfView / 2))) * (cam.ViewportSize.Y / 2)
	d = math.clamp(d, 10, cam.ViewportSize.Y * 2)
	local show = Aim.ShowCircle
	fovCircle.Visible = show
	fovGlow.Visible = show and Aim.CircleMode == _0OlllII0[403]
	fovCircle.Size = UDim2.fromOffset(d, d)
	fovGlow.Size = UDim2.fromOffset(d, d)
	fovStroke.Color = Aim.CircleColor
	glowStroke.Color = Aim.CircleColor
	fovCircle.BackgroundColor3 = Aim.CircleColor
	local filled = (Aim.CircleMode ~= _0OlllII0[521])
	fovCircle.BackgroundTransparency = filled and (1 - Aim.FillOpacity / 100) or 1
end
RunService.RenderStepped:Connect(updateCircle)

