			guard += 1
			for _, j in ipairs(joints) do
				local a, b = j.Part0, j.Part1
				if R[a] and not R[b] then
					R[b] = R[a] * j.C0 * j.C1:Inverse()
					changed = true
				elseif R[b] and not R[a] then
					R[a] = R[b] * j.C1 * j.C0:Inverse()
					changed = true
				end
			end
		end
