				local n = okf and NORMALS[fname]
				if part and part:IsA(_0OlllII0[235]) and n then
					local dir = F:VectorToObjectSpace(part.CFrame:VectorToWorldSpace(n))
					if dir.X * dir.X + dir.Z * dir.Z > 0.25 then
