	local function computeRel(rig)
		local rel, steps = rig.rel, rig.steps
		for i = 1, #steps do
			local st = steps[i]
			local cf = rel[st.p] * st.A
			local T = st.t
			if T then
				if st.inv then T = T:Inverse() end
				cf = cf * T * st.B
			elseif st.B then
				cf = cf * st.B
			end
			rel[st.c] = cf
		end
