	local function syncJoints(rig)
		local k = rig.k or 1
		local moved = 0
		local steps = rig.steps
		for i = 1, #steps do
			local st = steps[i]
			local rj = st.rj
			if rj then
				if rj.Parent then
					local t = rj.Transform
					if k ~= 1 then t = CFrame.new(t.Position * k) * t.Rotation end
					if st.last == nil or not t:FuzzyEq(st.last, 1e-4) then
						moved += 1
						st.last = t
						st.t = t
					end
				end
			end
		end
		return moved
	end

