	local function spawnTracer(from, to)
		local holder = Instance.new(_0OlllII0[461])
		holder.Anchored = true; holder.CanCollide = false; holder.CanQuery = false; holder.CanTouch = false
		holder.Transparency = 1; holder.Size = Vector3.one * 0.1; holder.CFrame = CFrame.new(from)
