			if side.Magnitude < 0.01 then side = Vector3.xAxis end
			local ctrl = (from + to) / 2 + (side.Unit + Vector3.yAxis * 0.5).Unit * len * 0.12
			pts = {}
			for i = 0, 12 do
				local t = i / 12
				table.insert(pts, from * (1 - t) ^ 2 + ctrl * 2 * (1 - t) * t + to * t ^ 2)
			end
		else
			pts = { from, to }
		end

