		if LocalPlayer.Character then ign[#ign + 1] = LocalPlayer.Character end
		local mineM = NB.CharRaw and NB.CharRaw(LocalPlayer)
		if mineM and mineM ~= LocalPlayer.Character then ign[#ign + 1] = mineM end
